/******************************************************************************/
/*                                                                            */
/* LogLPMT()                                                                  */
/*                                                                            */
/******************************************************************************/

VOID LogLPMT( LPMT p )                           /* LPMT                      */
{

   int i;                                        /* Loop variable             */

   /*
    * Log menu template structure contents if tracing API parameter contents
    * and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( ULONG ) ) ) && ( T_IsValidMem( p, p->len ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "len = 0x%08lX\n", p->len );

      if ( ( FIELDOFFSET( MT, codepage ) + sizeof( p->codepage ) ) <= p->len )
      {
         WriteLogWithPrefix( "codepage = 0x%04hX\n", p->codepage );

         if ( ( FIELDOFFSET( MT, reserved ) + sizeof( p->reserved ) ) <= p->len )
         {
            WriteLogWithPrefix( "reserved = 0x%04hX\n", p->reserved );

            if ( ( FIELDOFFSET( MT, cMti ) + sizeof( p->cMti ) ) <= p->len )
            {
               WriteLogWithPrefix( "cMti = 0x%04hX\n", p->cMti );

               /*
                * Log each MTI structure
                */
               for ( i = 0; i < p->cMti; i++ )
               {
                  WriteLogWithPrefix( "rgMti[ %d ]:\n", i );
                  INDENTLOGIN;

                  if ( ( sizeof( MT ) - sizeof( MTI ) + ( i * sizeof( MTI ) ) + FIELDOFFSET( MTI, afStyle ) + sizeof( p->rgMti[ i ].afStyle ) ) <= p->len )
                  {
                     WriteLogWithPrefix( "afStyle = 0x%04hX\n", p->rgMti[ i ].afStyle );

                     if ( ( sizeof( MT ) - sizeof( MTI ) + ( i * sizeof( MTI ) ) + FIELDOFFSET( MTI, pad ) + sizeof( p->rgMti[ i ].pad ) ) <= p->len )
                     {
                        WriteLogWithPrefix( "pad = 0x%04hX\n", p->rgMti[ i ].pad );

                        if ( ( sizeof( MT ) - sizeof( MTI ) + ( i * sizeof( MTI ) ) + FIELDOFFSET( MTI, idItem ) + sizeof( p->rgMti[ i ].idItem ) ) <= p->len )
                        {
                           WriteLogWithPrefix( "idItem = 0x%04hX\n", p->rgMti[ i ].idItem );

                           if ( ( sizeof( MT ) - sizeof( MTI ) + ( i * sizeof( MTI ) ) + FIELDOFFSET( MTI, c ) + sizeof( p->rgMti[ i ].c ) ) <= p->len )
                           {
                              WriteLogWithPrefix( "c = 0x%04hX\n", *( (PUSHORT)( &p->rgMti[ i ].c[ 0 ] ) ) );
                           }
                        }
                     }
                  }

                  INDENTLOGOUT;
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogLPMT() */

