/******************************************************************************/
/*                                                                            */
/* LogPBITMAPINFO2()                                                          */
/*                                                                            */
/******************************************************************************/

VOID LogPBITMAPINFO2( PBITMAPINFO2 p )           /* PBITMAPINFO2              */
{

   BOOL   bMore = FALSE;                         /* Log more indicator        */
   int    i;                                     /* Loop variable             */
   int    N;                                     /* Bits per pel              */
   RGB   *pRGB;                                  /* RGB pointer               */
   PRGB2  pRGB2;                                 /* RGB2 pointer              */
   ULONG  ulNumber;                              /* Number RGBs               */

   /*
    * Log fixed portion of bitmap information structure address and contents
    */
   LogPBITMAPINFOHEADER2( (PBITMAPINFOHEADER2)p );

   /*
    * Log RGB array portion of bitmap information structure if tracing API
    * parameter contents and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( ULONG ) ) ) )
   {
      INDENTLOGIN;

      /*
       * Log RGB array portion of BITMAPINFOHEADER
       */
      if ( ( p->cbFix == sizeof( BITMAPINFOHEADER ) ) && ( T_IsValidMem( p, sizeof( BITMAPINFOHEADER ) ) ) )
      {
         /*
          * Log RGB array portion of BITMAPINFOHEADER if valid bits per pel
          */
         if ( ( N = ((PBITMAPINFO)p)->cPlanes * ((PBITMAPINFO)p)->cBitCount ) <= 31 )
         {
            /*
             * Determine number RGBs in RGB array
             */
            ulNumber = ( N == 24 ? 0L : (ULONG)pow( (double)2, (double)N ) );

            /*
             * Log RGB array if valid array pointer
             */
            if ( T_IsValidMem( pRGB = (RGB *)( (ULONG)p + p->cbFix ), ulNumber * sizeof( RGB ) ) )
            {
               /*
                * Adjust number RGBs if length greater than maximum buffer
                * length
                */
               if ( ( ulMaxBufLen ) && ( ulMaxBufLen < ( ulNumber * sizeof( RGB ) ) ) )
               {
                  ulNumber = ulMaxBufLen / sizeof( RGB );
                  bMore = TRUE;
               }

               /*
                * Log each RGB
                */
               for ( i = 0; i < ulNumber; i++, pRGB++ )
               {
                  WriteLogWithPrefix( "argbColor[ %d ]: bBlue 0x%02X, bGreen 0x%02X, bRed 0x%02X\n", i, pRGB->bBlue, pRGB->bGreen, pRGB->bRed );
               }

               /*
                * Log more contents string if so indicated
                */
               if ( bMore )
               {
                  WriteLogWithPrefix( "%s\n", szMore );
               }
            }
         }
      }

      /*
       * Log RGB2 array portion of BITMAPINFOHEADER2
       */
      else if ( ( p->cbFix >= ( FIELDOFFSET( BITMAPINFOHEADER2, cBitCount ) + sizeof( p->cBitCount ) ) ) && ( T_IsValidMem( p, p->cbFix ) ) )
      {
         /*
          * Log RGB2 array portion of BITMAPINFOHEADER2 if valid bits per pel
          */
         if ( ( N = p->cPlanes * p->cBitCount ) <= 31 )
         {
            /*
             * Determine number of RGBs in RGB2 array
             */
            ulNumber = ( N == 24 ? MAX( p->cclrUsed, p->cclrImportant ) : (ULONG)pow( (double)2, (double)N ) );

            /*
             * Log RGB2 array if valid array pointer
             */
            if ( T_IsValidMem( pRGB2 = (PRGB2)( (ULONG)p + p->cbFix ), ulNumber * sizeof( RGB2 ) ) )
            {
               /*
                * Adjust number RGB2s if length greater than maximum buffer
                * length
                */
               if ( ( ulMaxBufLen ) && ( ulMaxBufLen < ( ulNumber * sizeof( RGB2 ) ) ) )
               {
                  ulNumber = ulMaxBufLen / sizeof( RGB2 );
                  bMore = TRUE;
               }

               /*
                * Log each RGB2
                */
               for ( i = 0; i < ulNumber; i++, pRGB2++ )
               {
                  WriteLogWithPrefix( "argbColor[ %d ]: bBlue 0x%02X, bGreen 0x%02X, bRed 0x%02X, fcOptions 0x%02X\n", i, pRGB2->bBlue, pRGB2->bGreen, pRGB2->bRed, pRGB2->fcOptions );
               }

               /*
                * Log more contents string if so indicated
                */
               if ( bMore )
               {
                  WriteLogWithPrefix( "%s\n", szMore );
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPBITMAPINFO2() */

/******************************************************************************/
/*                                                                            */
/* LogPBITMAPINFOHEADER2()                                                    */
/*                                                                            */
/******************************************************************************/

VOID LogPBITMAPINFOHEADER2(
                            PBITMAPINFOHEADER2 p /* PBITMAPINFOHEADER2        */
                          )
{

   /*
    * Log bitmap information header structure contents if tracing API
    * parameter contents and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( ULONG ) ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbFix = 0x%08lX\n", p->cbFix );

      /*
       * Log BITMAPINFOHEADER structure contents if valid pointer
       */
      if ( ( p->cbFix == sizeof( BITMAPINFOHEADER ) ) && ( T_IsValidMem( p, sizeof( BITMAPINFOHEADER ) ) ) )
      {
         WriteLogWithPrefix( "cx = 0x%04hX\n", ((PBITMAPINFOHEADER)p)->cx );
         WriteLogWithPrefix( "cy = 0x%04hX\n", ((PBITMAPINFOHEADER)p)->cy );
         WriteLogWithPrefix( "cPlanes = 0x%04hX\n", ((PBITMAPINFOHEADER)p)->cPlanes );
         WriteLogWithPrefix( "cBitCount = 0x%04hX\n", ((PBITMAPINFOHEADER)p)->cBitCount );
      }

      /*
       * Log BITMAPINFOHEADER2 structure contents if valid pointer
       */
      else if ( ( p->cbFix >= ( FIELDOFFSET( BITMAPINFOHEADER2, cBitCount ) + sizeof( p->cBitCount ) ) ) && ( T_IsValidMem( p, p->cbFix ) ) )
      {
         WriteLogWithPrefix( "cx = 0x%08lX\n", p->cx );
         WriteLogWithPrefix( "cy = 0x%08lX\n", p->cy );
         WriteLogWithPrefix( "cPlanes = 0x%04hX\n", p->cPlanes );
         WriteLogWithPrefix( "cBitCount = 0x%04hX\n", p->cBitCount );

         if ( ( FIELDOFFSET( BITMAPINFOHEADER2, ulCompression ) + sizeof( p->ulCompression ) ) <= p->cbFix )
         {
            WriteLogWithPrefix( "ulCompression = 0x%08lX\n", p->ulCompression );

            if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cbImage ) + sizeof( p->cbImage ) ) <= p->cbFix )
            {
               WriteLogWithPrefix( "cbImage = 0x%08lX\n", p->cbImage );

               if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cxResolution ) + sizeof( p->cxResolution ) ) <= p->cbFix )
               {
                  WriteLogWithPrefix( "cxResolution = 0x%08lX\n", p->cxResolution );

                  if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cyResolution ) + sizeof( p->cyResolution ) ) <= p->cbFix )
                  {
                     WriteLogWithPrefix( "cyResolution = 0x%08lX\n", p->cyResolution );

                     if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cclrUsed ) + sizeof( p->cclrUsed ) ) <= p->cbFix )
                     {
                        WriteLogWithPrefix( "cclrUsed = 0x%08lX\n", p->cclrUsed );

                        if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cclrImportant ) + sizeof( p->cclrImportant ) ) <= p->cbFix )
                        {
                           WriteLogWithPrefix( "cclrImportant = 0x%08lX\n", p->cclrImportant );

                           if ( ( FIELDOFFSET( BITMAPINFOHEADER2, usUnits ) + sizeof( p->usUnits ) ) <= p->cbFix )
                           {
                              WriteLogWithPrefix( "usUnits = 0x%04hX\n", p->usUnits );

                              if ( ( FIELDOFFSET( BITMAPINFOHEADER2, usReserved ) + sizeof( p->usReserved ) ) <= p->cbFix )
                              {
                                 WriteLogWithPrefix( "usReserved = 0x%04hX\n", p->usReserved );

                                 if ( ( FIELDOFFSET( BITMAPINFOHEADER2, usRecording ) + sizeof( p->usRecording ) ) <= p->cbFix )
                                 {
                                    WriteLogWithPrefix( "usRecording = 0x%04hX\n", p->usRecording );

                                    if ( ( FIELDOFFSET( BITMAPINFOHEADER2, usRendering ) + sizeof( p->usRendering ) ) <= p->cbFix )
                                    {
                                       WriteLogWithPrefix( "usRendering = 0x%04hX\n", p->usRendering );

                                       if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cSize1 ) + sizeof( p->cSize1 ) ) <= p->cbFix )
                                       {
                                          WriteLogWithPrefix( "cSize1 = 0x%08lX\n", p->cSize1 );

                                          if ( ( FIELDOFFSET( BITMAPINFOHEADER2, cSize2 ) + sizeof( p->cSize2 ) ) <= p->cbFix )
                                          {
                                             WriteLogWithPrefix( "cSize2 = 0x%08lX\n", p->cSize2 );

                                             if ( ( FIELDOFFSET( BITMAPINFOHEADER2, ulColorEncoding ) + sizeof( p->ulColorEncoding ) ) <= p->cbFix )
                                             {
                                                WriteLogWithPrefix( "ulColorEncoding = 0x%08lX\n", p->ulColorEncoding );

                                                if ( ( FIELDOFFSET( BITMAPINFOHEADER2, ulIdentifier ) + sizeof( p->ulIdentifier ) ) <= p->cbFix )
                                                {
                                                   WriteLogWithPrefix( "ulIdentifier = 0x%08lX\n", p->ulIdentifier );
                                                }
                                             }
                                          }
                                       }
                                    }
                                 }
                              }
                           }
                        }
                     }
                  }
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPBITMAPINFOHEADER2() */

/******************************************************************************/
/*                                                                            */
/* LogPBUNDLE()                                                               */
/*                                                                            */
/******************************************************************************/

VOID LogPBUNDLE( PBUNDLE p                       /* PBUNDLE                   */
               , LONG    lType                   /* Bundle type               */
               , BOOL    b32Bit                  /* 32-bit indicator          */
               )
{

   /*
    * Log bundle structure contents if tracing API parameter contents
    */
   if ( LOGLEVEL( L_CONTENTS ) )
   {
      INDENTLOGIN;

      /*
       * Log bundle structure contents based on bundle type
       */
      switch ( lType )
      {
         case PRIM_LINE:
            if ( T_IsValidMem( p, sizeof( LINEBUNDLE ) ) )
            {
               WriteLogWithPrefix( "lColor = 0x%08lX\n", ((PLINEBUNDLE)p)->lColor );
               WriteLogWithPrefix( "lBackColor = 0x%08lX\n", ((PLINEBUNDLE)p)->lBackColor );
               WriteLogWithPrefix( "usMixMode = 0x%04hX\n", ((PLINEBUNDLE)p)->usMixMode );
               WriteLogWithPrefix( "usBackMixMode = 0x%04hX\n", ((PLINEBUNDLE)p)->usBackMixMode );
               WriteLogWithPrefix( "fxWidth = " ); T_LogFIXED( ((PLINEBUNDLE)p)->fxWidth );
               WriteLogWithPrefix( "lGeomWidth = 0x%08lX\n", ((PLINEBUNDLE)p)->lGeomWidth );
               WriteLogWithPrefix( "usType = 0x%04hX\n", ((PLINEBUNDLE)p)->usType );
               WriteLogWithPrefix( "usEnd = 0x%04hX\n", ((PLINEBUNDLE)p)->usEnd );
               WriteLogWithPrefix( "usJoin = 0x%04hX\n", ((PLINEBUNDLE)p)->usJoin );

               if ( b32Bit )
               {
                  WriteLogWithPrefix( "usReserved = 0x%04hX\n", ((PLINEBUNDLE)p)->usReserved );
               }
            }

            break;

         case PRIM_CHAR:
            if ( T_IsValidMem( p, sizeof( CHARBUNDLE ) ) )
            {
               WriteLogWithPrefix( "lColor = 0x%08lX\n", ((PCHARBUNDLE)p)->lColor );
               WriteLogWithPrefix( "lBackColor = 0x%08lX\n", ((PCHARBUNDLE)p)->lBackColor );
               WriteLogWithPrefix( "usMixMode = 0x%04hX\n", ((PCHARBUNDLE)p)->usMixMode );
               WriteLogWithPrefix( "usBackMixMode = 0x%04hX\n", ((PCHARBUNDLE)p)->usBackMixMode );
               WriteLogWithPrefix( "usSet = 0x%04hX\n", ((PCHARBUNDLE)p)->usSet );
               WriteLogWithPrefix( "usPrecision = 0x%04hX\n", ((PCHARBUNDLE)p)->usPrecision );
               WriteLogWithPrefix( "sizfxCell:\n" );
               INDENTLOGIN;
               WriteLogWithPrefix( "cx = " ); T_LogFIXED( ((PCHARBUNDLE)p)->sizfxCell.cx );
               WriteLogWithPrefix( "cy = " ); T_LogFIXED( ((PCHARBUNDLE)p)->sizfxCell.cy );
               INDENTLOGOUT;
               WriteLogWithPrefix( "ptlAngle:\n" );
               INDENTLOGIN;
               WriteLogWithPrefix( "x = 0x%08lX\n", ((PCHARBUNDLE)p)->ptlAngle.x );
               WriteLogWithPrefix( "y = 0x%08lX\n", ((PCHARBUNDLE)p)->ptlAngle.y );
               INDENTLOGOUT;
               WriteLogWithPrefix( "ptlShear:\n" );
               INDENTLOGIN;
               WriteLogWithPrefix( "x = 0x%08lX\n", ((PCHARBUNDLE)p)->ptlShear.x );
               WriteLogWithPrefix( "y = 0x%08lX\n", ((PCHARBUNDLE)p)->ptlShear.y );
               INDENTLOGOUT;
               WriteLogWithPrefix( "usDirection = 0x%04hX\n", ((PCHARBUNDLE)p)->usDirection );
               WriteLogWithPrefix( "usTextAlign = 0x%04hX\n", ((PCHARBUNDLE)p)->usTextAlign );
               WriteLogWithPrefix( "fxExtra = " ); T_LogFIXED( ((PCHARBUNDLE)p)->fxExtra );
               WriteLogWithPrefix( "fxBreakExtra = " ); T_LogFIXED( ((PCHARBUNDLE)p)->fxBreakExtra );
            }

            break;

         case PRIM_MARKER:
            if ( T_IsValidMem( p, sizeof( MARKERBUNDLE ) ) )
            {
               WriteLogWithPrefix( "lColor = 0x%08lX\n", ((PMARKERBUNDLE)p)->lColor );
               WriteLogWithPrefix( "lBackColor = 0x%08lX\n", ((PMARKERBUNDLE)p)->lBackColor );
               WriteLogWithPrefix( "usMixMode = 0x%04hX\n", ((PMARKERBUNDLE)p)->usMixMode );
               WriteLogWithPrefix( "usBackMixMode = 0x%04hX\n", ((PMARKERBUNDLE)p)->usBackMixMode );
               WriteLogWithPrefix( "usSet = 0x%04hX\n", ((PMARKERBUNDLE)p)->usSet );
               WriteLogWithPrefix( "usSymbol = 0x%04hX\n", ((PMARKERBUNDLE)p)->usSymbol );
               WriteLogWithPrefix( "sizfxCell:" );
               INDENTLOGIN;
               WriteLogWithPrefix( "cx = " ); T_LogFIXED( ((PMARKERBUNDLE)p)->sizfxCell.cx );
               WriteLogWithPrefix( "cy = " ); T_LogFIXED( ((PMARKERBUNDLE)p)->sizfxCell.cy );
               INDENTLOGOUT;
            }

            break;

         case PRIM_AREA:
            if ( T_IsValidMem( p, sizeof( AREABUNDLE ) ) )
            {
               WriteLogWithPrefix( "lColor = 0x%08lX\n", ((PAREABUNDLE)p)->lColor );
               WriteLogWithPrefix( "lBackColor = 0x%08lX\n", ((PAREABUNDLE)p)->lBackColor );
               WriteLogWithPrefix( "usMixMode = 0x%04hX\n", ((PAREABUNDLE)p)->usMixMode );
               WriteLogWithPrefix( "usBackMixMode = 0x%04hX\n", ((PAREABUNDLE)p)->usBackMixMode );
               WriteLogWithPrefix( "usSet = 0x%04hX\n", ((PAREABUNDLE)p)->usSet );
               WriteLogWithPrefix( "usSymbol = 0x%04hX\n", ((PAREABUNDLE)p)->usSymbol );
               WriteLogWithPrefix( "ptlRefPoint:\n" );
               INDENTLOGIN;
               WriteLogWithPrefix( "x = 0x%08lX\n", ((PAREABUNDLE)p)->ptlRefPoint.x );
               WriteLogWithPrefix( "y = 0x%08lX\n", ((PAREABUNDLE)p)->ptlRefPoint.y );
               INDENTLOGOUT;
            }

            break;

         case PRIM_IMAGE:
            if ( T_IsValidMem( p, sizeof( IMAGEBUNDLE ) ) )
            {
               WriteLogWithPrefix( "lColor = 0x%08lX\n", ((PIMAGEBUNDLE)p)->lColor );
               WriteLogWithPrefix( "lBackColor = 0x%08lX\n", ((PIMAGEBUNDLE)p)->lBackColor );
               WriteLogWithPrefix( "usMixMode = 0x%04hX\n", ((PIMAGEBUNDLE)p)->usMixMode );
               WriteLogWithPrefix( "usBackMixMode = 0x%04hX\n", ((PIMAGEBUNDLE)p)->usBackMixMode );
            }

            break;
      }

      INDENTLOGOUT;
   }

}  /* LogPBUNDLE() */

