/******************************************************************************/
/*                                                                            */
/* LogPDDESTRUCT()                                                            */
/*                                                                            */
/******************************************************************************/

VOID LogPDDESTRUCT( PDDESTRUCT p )               /* PDDESTRUCT                */
{

   PCHAR pch;                                    /* Character pointer         */

   /*
    * Log DDE structure contents if tracing API parameter contents and valid
    * pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( ULONG ) ) ) && ( T_IsValidMem( p, p->cbData ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbData = 0x%08lX\n", p->cbData );

      if ( ( FIELDOFFSET( DDESTRUCT, fsStatus ) + sizeof( p->fsStatus ) ) <= p->cbData )
      {
         WriteLogWithPrefix( "fsStatus = 0x%04hX\n", p->fsStatus );

         if ( ( FIELDOFFSET( DDESTRUCT, usFormat ) + sizeof( p->usFormat ) ) <= p->cbData )
         {
            WriteLogWithPrefix( "usFormat = 0x%04hX\n", p->usFormat );

            if ( ( FIELDOFFSET( DDESTRUCT, offszItemName ) + sizeof( p->offszItemName ) ) <= p->cbData )
            {
               WriteLogWithPrefix( "offszItemName = 0x%04hX\n", p->offszItemName );

               if ( ( FIELDOFFSET( DDESTRUCT, offabData ) + sizeof( p->offabData ) ) <= p->cbData )
               {
                  WriteLogWithPrefix( "offabData = 0x%04hX\n", p->offabData );

                  pch = (PCHAR)p + p->offszItemName;
                  if ( p->offszItemName <= p->cbData )
                  {
                     WriteLogWithPrefix( "Item Name = \"%s\"\n", pch );

                     pch = (PCHAR)p + p->offabData;
                     if ( p->offabData <= p->cbData )
                     {
                        WriteLogWithPrefix( "Data:\n", pch ); T_LogCHARBuffer( pch, p->cbData - p->offabData + 1 );
                     }
                  }
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPDDESTRUCT() */

