/******************************************************************************/
/*                                                                            */
/* LogPDLGTEMPLATE()                                                          */
/*                                                                            */
/******************************************************************************/

VOID LogPDLGTEMPLATE( PDLGTEMPLATE p )           /* PDLGTEMPLATE              */
{

   int i = 0;                                    /* Loop variable             */

   /*
    * Log dialog template structure contents if tracing API parameter
    * contents and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( USHORT ) ) ) && ( T_IsValidMem( p, p->cbTemplate ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbTemplate = 0x%04hX\n", p->cbTemplate );

      if ( ( FIELDOFFSET( DLGTEMPLATE, type ) + sizeof( p->type ) ) <= p->cbTemplate )
      {
         WriteLogWithPrefix( "type = 0x%04hX\n", p->type );

         if ( ( FIELDOFFSET( DLGTEMPLATE, codepage ) + sizeof( p->codepage ) ) <= p->cbTemplate )
         {
            WriteLogWithPrefix( "codepage = 0x%04hX\n", p->codepage );

            if ( ( FIELDOFFSET( DLGTEMPLATE, offadlgti ) + sizeof( p->offadlgti ) ) <= p->cbTemplate )
            {
               WriteLogWithPrefix( "offadlgti = 0x%04hX\n", p->offadlgti );

               if ( ( FIELDOFFSET( DLGTEMPLATE, fsTemplateStatus ) + sizeof( p->fsTemplateStatus ) ) <= p->cbTemplate )
               {
                  WriteLogWithPrefix( "fsTemplateStatus = 0x%04hX\n", p->fsTemplateStatus );

                  if ( ( FIELDOFFSET( DLGTEMPLATE, iItemFocus ) + sizeof( p->iItemFocus ) ) <= p->cbTemplate )
                  {
                     WriteLogWithPrefix( "iItemFocus = 0x%04hX\n", p->iItemFocus );

                     if ( ( FIELDOFFSET( DLGTEMPLATE, coffPresParams ) + sizeof( p->coffPresParams ) ) <= p->cbTemplate )
                     {
                        WriteLogWithPrefix( "coffPresParams = 0x%04hX\n", p->coffPresParams );
                     }

                     while ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) ) <= p->cbTemplate )
                     {
                        WriteLogWithPrefix( "adlgti[ %d ]:\n", i );
                        INDENTLOGIN;

                        if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, fsItemStatus ) + sizeof( p->adlgti[ i ].fsItemStatus ) ) <= p->cbTemplate )
                        {
                           WriteLogWithPrefix( "fsItemStatus = 0x%04hX\n", p->adlgti[ i ].fsItemStatus );

                           if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, cChildren ) + sizeof( p->adlgti[ i ].cChildren ) ) <= p->cbTemplate )
                           {
                              WriteLogWithPrefix( "cChildren = 0x%04hX\n", p->adlgti[ i ].cChildren );

                              if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, cchClassName ) + sizeof( p->adlgti[ i ].cchClassName ) ) <= p->cbTemplate )
                              {
                                 WriteLogWithPrefix( "cchClassName = 0x%04hX\n", p->adlgti[ i ].cchClassName );

                                 if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, offClassName ) + sizeof( p->adlgti[ i ].offClassName ) ) <= p->cbTemplate )
                                 {
                                    WriteLogWithPrefix( "offClassName = 0x%04hX\n", p->adlgti[ i ].offClassName );

                                    if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, cchText ) + sizeof( p->adlgti[ i ].cchText ) ) <= p->cbTemplate )
                                    {
                                       WriteLogWithPrefix( "cchText = 0x%04hX\n", p->adlgti[ i ].cchText );

                                       if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, offText ) + sizeof( p->adlgti[ i ].offText ) ) <= p->cbTemplate )
                                       {
                                          WriteLogWithPrefix( "offText = 0x%04hX\n", p->adlgti[ i ].offText );

                                          if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, flStyle ) + sizeof( p->adlgti[ i ].flStyle ) ) <= p->cbTemplate )
                                          {
                                             WriteLogWithPrefix( "flStyle = 0x%08lX\n", p->adlgti[ i ].flStyle );

                                             if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, x ) + sizeof( p->adlgti[ i ].x ) ) <= p->cbTemplate )
                                             {
                                                WriteLogWithPrefix( "x = 0x%04hX\n", p->adlgti[ i ].x );

                                                if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, y ) + sizeof( p->adlgti[ i ].y ) ) <= p->cbTemplate )
                                                {
                                                   WriteLogWithPrefix( "y = 0x%04hX\n", p->adlgti[ i ].y );

                                                   if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, cx ) + sizeof( p->adlgti[ i ].cx ) ) <= p->cbTemplate )
                                                   {
                                                      WriteLogWithPrefix( "cx = 0x%04hX\n", p->adlgti[ i ].cx );

                                                      if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, cy ) + sizeof( p->adlgti[ i ].cy ) ) <= p->cbTemplate )
                                                      {
                                                         WriteLogWithPrefix( "cy = 0x%04hX\n", p->adlgti[ i ].cy );

                                                         if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, id ) + sizeof( p->adlgti[ i ].id ) ) <= p->cbTemplate )
                                                         {
                                                            WriteLogWithPrefix( "id = 0x%04hX\n", p->adlgti[ i ].id );

                                                            if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, offPresParams ) + sizeof( p->adlgti[ i ].offPresParams ) ) <= p->cbTemplate )
                                                            {
                                                               WriteLogWithPrefix( "offPresParams = 0x%04hX\n", p->adlgti[ i ].offPresParams );

                                                               if ( ( sizeof( DLGTEMPLATE ) - sizeof( DLGTITEM ) + ( i * sizeof( DLGTITEM ) ) + FIELDOFFSET( DLGTITEM, offCtlData ) + sizeof( p->adlgti[ i ].offCtlData ) ) <= p->cbTemplate )
                                                               {
                                                                  WriteLogWithPrefix( "offCtlData = 0x%04hX\n", p->adlgti[ i ].offCtlData );
                                                               }
                                                            }
                                                         }
                                                      }
                                                   }
                                                }
                                             }
                                          }
                                       }
                                    }
                                 }
                              }
                           }
                        }

                        INDENTLOGOUT;
                        i++;
                     }
                  }
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPDLGTEMPLATE() */

/******************************************************************************/
/*                                                                            */
/* LogPDRAGINFO()                                                             */
/*                                                                            */
/******************************************************************************/

VOID LogPDRAGINFO( PDRAGINFO p )                 /* PDRAGINFO                 */
{

   int       i;                                  /* Loop variable             */
   PDRAGITEM pDRAGITEM;                          /* Drag object pointer       */
   ULONG     ulLogLen;                           /* Number bytes logged       */

   /*
    * Log drag information structure contents if tracing API parameter contents
    * and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( ULONG ) ) ) && ( T_IsValidMem( p, p->cbDraginfo ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbDraginfo = 0x%08lX\n", p->cbDraginfo );

      if ( ( FIELDOFFSET( DRAGINFO, cbDragitem ) + sizeof( p->cbDragitem ) ) <= p->cbDraginfo )
      {
         WriteLogWithPrefix( "cbDragitem = 0x%04hX\n", p->cbDragitem );

         if ( ( FIELDOFFSET( DRAGINFO, usOperation ) + sizeof( p->usOperation ) ) <= p->cbDraginfo )
         {
            WriteLogWithPrefix( "usOperation = 0x%04hX\n", p->usOperation );

            if ( ( FIELDOFFSET( DRAGINFO, hwndSource ) + sizeof( p->hwndSource ) ) <= p->cbDraginfo )
            {
               WriteLogWithPrefix( "hwndSource = 0x%08lX\n", p->hwndSource );

               if ( ( FIELDOFFSET( DRAGINFO, xDrop ) + sizeof( p->xDrop ) ) <= p->cbDraginfo )
               {
                  WriteLogWithPrefix( "xDrop = 0x%04hX\n", p->xDrop );

                  if ( ( FIELDOFFSET( DRAGINFO, yDrop ) + sizeof( p->yDrop ) ) <= p->cbDraginfo )
                  {
                     WriteLogWithPrefix( "yDrop = 0x%04hX\n", p->yDrop );

                     if ( ( FIELDOFFSET( DRAGINFO, cditem ) + sizeof( p->cditem ) ) <= p->cbDraginfo )
                     {
                        WriteLogWithPrefix( "cditem = 0x%04hX\n", p->cditem );

                        if ( ( FIELDOFFSET( DRAGINFO, usReserved ) + sizeof( p->usReserved ) ) <= p->cbDraginfo )
                        {
                           WriteLogWithPrefix( "usReserved = 0x%04hX\n", p->usReserved );

                           /*
                            * Log each DRAGITEM structure
                            */
                           for ( i = 0, ulLogLen = sizeof( DRAGINFO ), pDRAGITEM = (PDRAGITEM)( (ULONG)p + sizeof( DRAGINFO ) )
                               ; ( i < p->cditem ) && ( ulLogLen <= ( p->cbDraginfo - p->cbDragitem ) )
                               ; i++, ulLogLen += p->cbDragitem, pDRAGITEM = (PDRAGITEM)( (ULONG)pDRAGITEM + p->cbDragitem )
                               )
                           {
                              WriteLogWithPrefix( "DRAGITEM[ %d ]:\n", i );
                              INDENTLOGIN;

                              if ( ( FIELDOFFSET( DRAGITEM, hwndItem ) + sizeof( pDRAGITEM->hwndItem ) ) <= p->cbDragitem )
                              {
                                 WriteLogWithPrefix( "hwndItem = 0x%08lX\n", pDRAGITEM->hwndItem );

                                 if ( ( FIELDOFFSET( DRAGITEM, ulItemID ) + sizeof( pDRAGITEM->ulItemID ) ) <= p->cbDragitem )
                                 {
                                    WriteLogWithPrefix( "ulItemID = 0x%08lX\n", pDRAGITEM->ulItemID );

                                    if ( ( FIELDOFFSET( DRAGITEM, hstrType ) + sizeof( pDRAGITEM->hstrType ) ) <= p->cbDragitem )
                                    {
                                       WriteLogWithPrefix( "hstrType = 0x%08lX\n", pDRAGITEM->hstrType );

                                       if ( ( FIELDOFFSET( DRAGITEM, hstrRMF ) + sizeof( pDRAGITEM->hstrRMF ) ) <= p->cbDragitem )
                                       {
                                          WriteLogWithPrefix( "hstrRMF = 0x%08lX\n", pDRAGITEM->hstrRMF );

                                          if ( ( FIELDOFFSET( DRAGITEM, hstrContainerName ) + sizeof( pDRAGITEM->hstrContainerName ) ) <= p->cbDragitem )
                                          {
                                             WriteLogWithPrefix( "hstrContainerName = 0x%08lX\n", pDRAGITEM->hstrContainerName );

                                             if ( ( FIELDOFFSET( DRAGITEM, hstrSourceName ) + sizeof( pDRAGITEM->hstrSourceName ) ) <= p->cbDragitem )
                                             {
                                                WriteLogWithPrefix( "hstrSourceName = 0x%08lX\n", pDRAGITEM->hstrSourceName );

                                                if ( ( FIELDOFFSET( DRAGITEM, hstrTargetName ) + sizeof( pDRAGITEM->hstrTargetName ) ) <= p->cbDragitem )
                                                {
                                                   WriteLogWithPrefix( "hstrTargetName = 0x%08lX\n", pDRAGITEM->hstrTargetName );

                                                   if ( ( FIELDOFFSET( DRAGITEM, cxOffset ) + sizeof( pDRAGITEM->cxOffset ) ) <= p->cbDragitem )
                                                   {
                                                      WriteLogWithPrefix( "cxOffset = 0x%04hX\n", pDRAGITEM->cxOffset );

                                                      if ( ( FIELDOFFSET( DRAGITEM, cyOffset ) + sizeof( pDRAGITEM->cyOffset ) ) <= p->cbDragitem )
                                                      {
                                                         WriteLogWithPrefix( "cyOffset = 0x%04hX\n", pDRAGITEM->cyOffset );

                                                         if ( ( FIELDOFFSET( DRAGITEM, fsControl ) + sizeof( pDRAGITEM->fsControl ) ) <= p->cbDragitem )
                                                         {
                                                            WriteLogWithPrefix( "fsControl = 0x%04hX\n", pDRAGITEM->fsControl );

                                                            if ( ( FIELDOFFSET( DRAGITEM, fsSupportedOps ) + sizeof( pDRAGITEM->fsSupportedOps ) ) <= p->cbDragitem )
                                                            {
                                                               WriteLogWithPrefix( "fsSupportedOps = 0x%04hX\n", pDRAGITEM->fsSupportedOps );
                                                            }
                                                         }
                                                      }
                                                   }
                                                }
                                             }
                                          }
                                       }
                                    }
                                 }
                              }

                              INDENTLOGOUT;
                           }
                        }
                     }
                  }
               }
            }
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPDRAGINFO() */

