/******************************************************************************/
/*                                                                            */
/* LogPFEALIST()                                                              */
/*                                                                            */
/******************************************************************************/

VOID LogPFEALIST( PFEALIST16 p )                 /* PFEALIST                  */
{

#if ( ( defined( INTEL ) ) && ( defined( T_16BIT ) ) )
   int     i;                                    /* Loop variable             */
   PCHAR16 pch;                                  /* Character pointer         */
   PFEA16  pFEA;                                 /* PFEA                      */

   /*
    * Log full extended attributes list structure contents if valid pointer
    */
   if ( T_IsValidMem16( p, sizeof( FEALIST ) ) )
   {
      WriteLogWithPrefix( "cbList = 0x%08lX\n", p->cbList );

      /*
       * Done logging if no full extended attributes structures in list
       * structure
       */
      if ( !p->cbList )
      {
         return;
      }

      i = 0;
      pch = (PCHAR16)p + sizeof( p->cbList );

      /*
       * Log each FEA structure
       */
      while ( pch < (PCHAR16)p + p->cbList )
      {
         pFEA = (PFEA16)pch;
         WriteLogWithPrefix( "pFEA[ %d ] = 0x%04hX:%04hX\n", i, HIWORD( pFEA ), LOWORD( pFEA ) );
         INDENTLOGIN;
         WriteLogWithPrefix( "fEA = 0x%02X\n", pFEA->fEA );
         WriteLogWithPrefix( "cbName = 0x%02X\n", pFEA->cbName );
         WriteLogWithPrefix( "cbValue = 0x%04hX\n", pFEA->cbValue );
         pch += sizeof( FEA );

         if ( pFEA->cbName )
         {
            WriteLogWithPrefix( "EA Name = \"%s\"\n", (PCHAR)pch );
         }

         pch += pFEA->cbName + 1;

         if ( pFEA->cbValue )
         {
            WriteLogWithPrefix( "EA Value:\n" );
         }

         T_LogCHARBuffer( pch, pFEA->cbValue );
         INDENTLOGOUT;

         i++;
         pch += pFEA->cbValue;
      }
   }
#endif

}  /* LogPFEALIST() */

/******************************************************************************/
/*                                                                            */
/* LogPFEA2LIST()                                                             */
/*                                                                            */
/******************************************************************************/

VOID LogPFEA2LIST( PFEA2LIST p )                 /* PFEA2LIST                 */
{

   int   i;                                      /* Loop variable             */
   PCHAR pch;                                    /* Character pointer         */
   PFEA2 pFEA2;                                  /* PFEA2                     */

   /*
    * Log full extended attributes list structure contents if valid pointer
    */
   if ( T_IsValidMem( p, sizeof( FEA2LIST ) ) )
   {
      WriteLogWithPrefix( "cbList = 0x%08lX\n", p->cbList );

      /*
       * Done logging if no full extended attributes structures in list
       * structure
       */
      if ( !p->cbList )
      {
         return;
      }

      i = 0;
      pch = (PCHAR)p + sizeof( p->cbList );

      /*
       * Log each FEA2 structure
       */
      do
      {
         pFEA2 = (PFEA2)pch;
         WriteLogWithPrefix( "pFEA2[ %d ] = 0x%08lX\n", i, pFEA2 );
         INDENTLOGIN;
         WriteLogWithPrefix( "oNextEntryOffset = 0x%08lX\n", pFEA2->oNextEntryOffset );
         WriteLogWithPrefix( "fEA = 0x%02X\n", pFEA2->fEA );
         WriteLogWithPrefix( "cbName = 0x%02X\n", pFEA2->cbName );
         WriteLogWithPrefix( "cbValue = 0x%04hX\n", pFEA2->cbValue );
         WriteLogWithPrefix( "szName = \"%s\"\n", pFEA2->szName );

         if ( pFEA2->cbValue )
         {
            WriteLogWithPrefix( "EA Value:\n" );
         }

         T_LogCHARBuffer( pFEA2->szName + pFEA2->cbName + 1, pFEA2->cbValue );
         INDENTLOGOUT;

         i++;
         pch += pFEA2->oNextEntryOffset;
      }  while ( pFEA2->oNextEntryOffset );
   }

}  /* LogPFEA2LIST() */

/******************************************************************************/
/*                                                                            */
/* LogPFILEFINDBUF()                                                          */
/*                                                                            */
/******************************************************************************/

VOID LogPFILEFINDBUF( PFILEFINDBUF16 p           /* PFILEFINDBUF              */
                    , USHORT         usNumber    /* Number PFILEFINDBUFs      */
                    )
{

#if ( ( defined( INTEL ) ) && ( defined( T_16BIT ) ) )
   int     i;                                    /* Loop variable             */
   PCHAR16 pch;                                  /* Character pointer         */

   INDENTLOGIN;

   /*
    * Log each FILEFINDBUF structure
    */
   for ( i = 0, pch = (PCHAR16)p; i < usNumber; i++, pch += ( 3 * sizeof( FDATE ) ) + ( 3 * sizeof( FTIME ) ) + ( 2 * sizeof( ULONG ) ) + sizeof( USHORT ) + ((PFILEFINDBUF)pch)->cchName + ( 2 * sizeof( CHAR ) ) )
   {
      WriteLogWithPrefix( "pFILEFINDBUF[ %d ] = 0x%04hX:%04hX\n", i, HIWORD( pch ), LOWORD( pch ) );
      INDENTLOGIN;
      WriteLogWithPrefix( "fdateCreation = %02d/%02d/%04d\n", ((PFILEFINDBUF)pch)->fdateCreation.month, ((PFILEFINDBUF)pch)->fdateCreation.day, ((PFILEFINDBUF)pch)->fdateCreation.year + FDATE_BASEYR );
      WriteLogWithPrefix( "ftimeCreation = %02d:%02d:%02d\n", ((PFILEFINDBUF)pch)->ftimeCreation.hours, ((PFILEFINDBUF)pch)->ftimeCreation.minutes, ((PFILEFINDBUF)pch)->ftimeCreation.twosecs * 2 );
      WriteLogWithPrefix( "fdateLastAccess = %02d/%02d/%04d\n", ((PFILEFINDBUF)pch)->fdateLastAccess.month, ((PFILEFINDBUF)pch)->fdateLastAccess.day, ((PFILEFINDBUF)pch)->fdateLastAccess.year + FDATE_BASEYR );
      WriteLogWithPrefix( "ftimeLastAccess = %02d:%02d:%02d\n", ((PFILEFINDBUF)pch)->ftimeLastAccess.hours, ((PFILEFINDBUF)pch)->ftimeLastAccess.minutes, ((PFILEFINDBUF)pch)->ftimeLastAccess.twosecs * 2 );
      WriteLogWithPrefix( "fdateLastWrite = %02d/%02d/%04d\n", ((PFILEFINDBUF)pch)->fdateLastWrite.month, ((PFILEFINDBUF)pch)->fdateLastWrite.day, ((PFILEFINDBUF)pch)->fdateLastWrite.year + FDATE_BASEYR );
      WriteLogWithPrefix( "ftimeLastWrite = %02d:%02d:%02d\n", ((PFILEFINDBUF)pch)->ftimeLastWrite.hours, ((PFILEFINDBUF)pch)->ftimeLastWrite.minutes, ((PFILEFINDBUF)pch)->ftimeLastWrite.twosecs * 2 );
      WriteLogWithPrefix( "cbFile = 0x%08lX\n", ((PFILEFINDBUF)pch)->cbFile );
      WriteLogWithPrefix( "cbFileAlloc = 0x%08lX\n", ((PFILEFINDBUF)pch)->cbFileAlloc );
      WriteLogWithPrefix( "attrFile = 0x%04hX\n", ((PFILEFINDBUF)pch)->attrFile );
      WriteLogWithPrefix( "cchName = 0x%02X\n", ((PFILEFINDBUF)pch)->cchName );
      WriteLogWithPrefix( "achName = \"%s\"\n", (PCHAR)((PFILEFINDBUF)pch)->achName );
      INDENTLOGOUT;
   }

   INDENTLOGOUT;
#endif

}  /* LogPFILEFINDBUF() */

