      WriteLogWithPrefix( "fdateLastWrite = %02d/%02d/%04d\n", ((PFILEFINDBUF4)pch)->fdateLastWrite.month, ((PFILEFINDBUF4)pch)->fdateLastWrite.day, ((PFILEFINDBUF4)pch)->fdateLastWrite.year + FDATE_BASEYR );
      WriteLogWithPrefix( "ftimeLastWrite = %02d:%02d:%02d\n", ((PFILEFINDBUF4)pch)->ftimeLastWrite.hours, ((PFILEFINDBUF4)pch)->ftimeLastWrite.minutes, ((PFILEFINDBUF4)pch)->ftimeLastWrite.twosecs * 2 );
      WriteLogWithPrefix( "cbFile = 0x%08lX\n", ((PFILEFINDBUF4)pch)->cbFile );
      WriteLogWithPrefix( "cbFileAlloc = 0x%08lX\n", ((PFILEFINDBUF4)pch)->cbFileAlloc );
      WriteLogWithPrefix( "attrFile = 0x%08lX\n", ((PFILEFINDBUF4)pch)->attrFile );
      WriteLogWithPrefix( "cbList = 0x%08lX\n", ((PFILEFINDBUF4)pch)->cbList );
      WriteLogWithPrefix( "cchName = 0x%02X\n", ((PFILEFINDBUF4)pch)->cchName );
