/******************************************************************************/
/*                                                                            */
/* LogPGEALIST()                                                              */
/*                                                                            */
/******************************************************************************/

VOID LogPGEALIST( PGEALIST16 p )                 /* PGEALIST                  */
{

#if ( ( defined( INTEL ) ) && ( defined( T_16BIT ) ) )
   int     i;                                    /* Loop variable             */
   PCHAR16 pch;                                  /* Character pointer         */
   PGEA16  pGEA;                                 /* PGEA                      */

   /*
    * Log get extended attributes list structure contents if valid pointer
    */
   if ( T_IsValidMem16( p, sizeof( GEALIST ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbList = 0x%08lX\n", p->cbList );

      /*
       * Done logging if no get extended attributes structures in list
       * structure
       */
      if ( !p->cbList )
      {
         return;
      }

      i = 0;
      pch = (PCHAR)p + sizeof( p->cbList );

      /*
       * Log each GEA structure
       */
      while ( pch < (PCHAR16)p + p->cbList )
      {
         pGEA = (PGEA16)pch;
         WriteLogWithPrefix( "pGEA[ %d ] = 0x%04hX:%04hX\n", i, HIWORD( pGEA ), LOWORD( pGEA ) );
         INDENTLOGIN;
         WriteLogWithPrefix( "cbName = 0x%02X\n", pGEA->cbName );
         WriteLogWithPrefix( "szName = \"%s\"\n", (PCHAR)pGEA->szName );
         INDENTLOGOUT;

         i++;
         pch += sizeof( GEA ) + pGEA->cbName;
      }

      INDENTLOGOUT;
   }
#endif

}  /* LogPGEALIST() */

/******************************************************************************/
/*                                                                            */
/* LogPGEA2LIST()                                                             */
/*                                                                            */
/******************************************************************************/

VOID LogPGEA2LIST( PGEA2LIST p )                 /* PGEA2LIST                 */
{

   int   i;                                      /* Loop variable             */
   PCHAR pch;                                    /* Character pointer         */
   PGEA2 pGEA2;                                  /* PGEA2                     */

   /*
    * Log get extended attributes list structure contents if valid pointer
    */
   if ( T_IsValidMem( p, sizeof( GEA2LIST ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "cbList = 0x%08lX\n", p->cbList );

      /*
       * Done logging if no get extended attributes structures in list
       * structure
       */
      if ( !p->cbList )
      {
         return;
      }

      i = 0;
      pch = (PCHAR)p + sizeof( p->cbList );

      /*
       * Log each GEA2 structure
       */
      do
      {
         pGEA2 = (PGEA2)pch;
         WriteLogWithPrefix( "pGEA2[ %d ] = 0x%08lX\n", i, pGEA2 );
         INDENTLOGIN;
         WriteLogWithPrefix( "oNextEntryOffset = 0x%08lX\n", pGEA2->oNextEntryOffset );
         WriteLogWithPrefix( "cbName = 0x%02X\n", pGEA2->cbName );
         WriteLogWithPrefix( "szName = \"%s\"\n", pGEA2->szName );
         INDENTLOGOUT;

         i++;
         pch += pGEA2->oNextEntryOffset;
      }  while ( pGEA2->oNextEntryOffset );

      INDENTLOGOUT;
   }

}  /* LogPGEA2LIST() */

