/******************************************************************************/
/*                                                                            */
/* LogPMError()                                                               */
/*                                                                            */
/******************************************************************************/

VOID LogPMError( VOID )                          /* No parameters             */
{

   PCHAR   szError = NULL;                       /* Error string              */
   PCHAR   szSeverity;                           /* Severity string           */
   ERRORID ulErrorID;                            /* Error identifier          */
   USHORT  usError;                              /* Error number              */
   USHORT  usSeverity;                           /* Severity number           */

   /*
    * Log error identifier, severity string, and error string if able to obtain
    * Presentation Manager error identifier
    */
   if ( ( ulErrorID = WinGetLastError( WinInitialize( 0L ) ) ) != 0L )
   {
      /*
       * Save Presentation Manager error identifier
       */
      T_PMErrorID[ T_GetTID( ) ] = ulErrorID;

      /*
       * Obtain severity number and error number
       */
      usSeverity = ERRORIDSEV( ulErrorID );
      usError = ERRORIDERROR( ulErrorID );

      /*
       * Error number zero
       */
      if ( !usError )
      {
         szError = "PMERR_OK";
      }

      /*
       * Error number falls within bounds of szPMErr1001To1059 array
       */
      else if ( ( usError >= 0x1001 ) && ( usError <= 0x1059 ) )
      {
         szError = szPMErr1001To1059[ usError - 0x1001 ];
      }

      /*
       * Error number falls within bounds of szPMErr10F0To1136 array
       */
      else if ( ( usError >= 0x10F0 ) && ( usError <= 0x1136 ) )
      {
         szError = szPMErr10F0To1136[ usError - 0x10F0 ];
      }

      /*
       * Error number falls within bounds of szPMErr1200To120E array
       */
      else if ( ( usError >= 0x1200 ) && ( usError <= 0x120E ) )
      {
         szError = szPMErr1200To120E[ usError - 0x1200 ];
      }

      /*
       * Error number falls within bounds of szPMErr1301To130D array
       */
      else if ( ( usError >= 0x1301 ) && ( usError <= 0x130D ) )
      {
         szError = szPMErr1301To130D[ usError - 0x1301 ];
      }

      /*
       * Error number falls within bounds of szPMErr1401To140F array
       */
      else if ( ( usError >= 0x1401 ) && ( usError <= 0x140F ) )
      {
         szError = szPMErr1401To140F[ usError - 0x1401 ];
      }

      /*
       * Error number falls within bounds of szPMErr1501To1534 array
       */
      else if ( ( usError >= 0x1501 ) && ( usError <= 0x1534 ) )
      {
         szError = szPMErr1501To1534[ usError - 0x1501 ];
      }

      /*
       * Error number falls within bounds of szPMErr1601To165A array
       */
      else if ( ( usError >= 0x1601 ) && ( usError <= 0x165A ) )
      {
         szError = szPMErr1601To165A[ usError - 0x1601 ];
      }

      /*
       * Error number falls within bounds of szPMErr1700To1721 array
       */
      else if ( ( usError >= 0x1700 ) && ( usError <= 0x1721 ) )
      {
         szError = szPMErr1700To1721[ usError - 0x1700 ];
      }

      /*
       * Error number falls within bounds of szPMErr2001To2120 array
       */
      else if ( ( usError >= 0x2001 ) && ( usError <= 0x2120 ) )
      {
         szError = szPMErr2001To2120[ usError - 0x2001 ];
      }

      /*
       * Error number falls within bounds of szPMErr3001To3012 array
       */
      else if ( ( usError >= 0x3001 ) && ( usError <= 0x3012 ) )
      {
         szError = szPMErr3001To3012[ usError - 0x3001 ];
      }

      /*
       * Error number falls within bounds of szPMErr4001To4040 array
       */
      else if ( ( usError >= 0x4001 ) && ( usError <= 0x4040 ) )
      {
         szError = szPMErr4001To4040[ usError - 0x4001 ];
      }

      /*
       * Error number falls within bounds of szPMErr4FA1To5010 array
       */
      else if ( ( usError >= 0x4FA1 ) && ( usError <= 0x5010 ) )
      {
         szError = szPMErr4FA1To5010[ usError - 0x4FA1 ];
      }

      /*
       * Error number falls within bounds of szNErr0836To0878 array
       */
      else if ( ( usError >= 0x0836 ) && ( usError <= 0x0878 ) )
      {
         szError = szNErr0836To0878[ usError - 0x0836 ];
      }

      /*
       * Error number falls within bounds of szNErr0925To0965 array
       */
      else if ( ( usError >= 0x0925 ) && ( usError <= 0x0965 ) )
      {
         szError = szNErr0925To0965[ usError - 0x0925 ];
      }

      /*
       * Obtain severity string from severity number
       */
      switch ( usSeverity )
      {
         case 0x0000: szSeverity = "SEVERITY_NOERROR";       break;
         case 0x0004: szSeverity = "SEVERITY_WARNING";       break;
         case 0x0008: szSeverity = "SEVERITY_ERROR";         break;
         case 0x000C: szSeverity = "SEVERITY_SEVERE";        break;
         case 0x0010: szSeverity = "SEVERITY_UNRECOVERABLE"; break;
         default    : szSeverity = szUnknown;
      }

      /*
       * Log error identifier, severity string, and error string
       */
      WriteLog( ", Error ID = 0x%08lX (%s, %s)", ulErrorID, szSeverity, szError ? szError : szUnknown );
   }

}  /* LogPMError() */

/******************************************************************************/
/*                                                                            */
/* LogPMGPIGroups()                                                           */
/*                                                                            */
/******************************************************************************/

VOID LogPMGPIGroups( ULONG ulGroups )            /* PMGPI API groups          */
{

   BOOL  bComma = FALSE;                         /* Log comma indicator       */
   int   i;                                      /* Loop variable             */
   ULONG ulNumGrp = 0L;                          /* Number API group bits set */

   /*
    * Log "ALL" if all PMGPI API groups bits set
    */
   if ( ulGroups == W_ALL )
   {
      WriteLog( "ALL" );
   }

   /*
    * Log each API group if not all PMGPI API groups bits set
    */
   else
   {
      /*
       * Log number of PMGPI API group bits set
       */
      for ( i = 0; i < sizeof( szGpiGroups ) / sizeof( PCHAR ); i++ )
      {
         /*
          * Increment number of PMGPI API group bits set if bit set
          */
         if ( FLAGSET( ulGroups, 1 << i ) )
         {
            ulNumGrp++;
         }
      }

      /*
       * Log each API group being traced if number of PMGPI API group bit sets
       * is less than half the total number of PMGPI API groups
       */
      if ( ulNumGrp < ( sizeof( szGpiGroups ) / sizeof( PCHAR ) ) / 2 )
      {
         /*
          * Log each API group being traced
          */
         for ( i = 0; i < sizeof( szGpiGroups ) / sizeof( PCHAR ); i++ )
         {
            /*
             * Log API group if corresponding PMGPI API group bit set
             */
            if ( FLAGSET( ulGroups, 1 << i ) )
            {
               /*
                * Log comma if so indicated
                */
               if ( bComma )
               {
                  fputc( ',', fpLogFile );
               }

               /*
                * Log API group
                */
               WriteLog( "%s", szGpiGroups[ i ] );

               /*
                * Indicate log comma
                */
               bComma = TRUE;
            }
         }
      }

      /*
       * Log "ALL" followed by each API group not being traced if number of
       * PMGPI API group bit sets is more than half the total number of PMGPI
       * API groups
       */
      else
      {
         /*
          * Log "ALL"
          */
         WriteLog( "ALL" );

         /*
          * Log each API group not being traced
          */
         for ( i = 0; i < sizeof( szGpiGroups ) / sizeof( PCHAR ); i++ )
         {
            /*
             * Log API group if corresponding PMGPI API group bit clear
             */
            if ( FLAGCLR( ulGroups, 1 << i ) )
            {
               /*
                * Log API group
                */
               WriteLog( ",NO%s", szGpiGroups[ i ] );
            }
         }
      }
   }

}  /* LogPMGPIGroups() */

