/******************************************************************************/
/*                                                                            */
/* LogPPRPORTINFO()                                                           */
/*                                                                            */
/******************************************************************************/

VOID LogPPRPORTINFO( PVOID pInfo                 /* PPRPORTINFO               */
                   , ULONG ulLength              /* PPRPORTINFO length        */
                   , ULONG ulLevel               /* PPRPORTINFO level         */
                   )
{

   /*
    * Log port information structure contents if tracing API parameter contents
    * and valid pointer
    */
   if ( T_IsValidMem( pInfo, ulLength ) )
   {
      INDENTLOGIN;

      /*
       * Log port information structure contents based on level
       */
      switch ( ulLevel )
      {
         case 0:
            if ( ( FIELDOFFSET( PRPORTINFO, szPortName ) + sizeof( ((PPRPORTINFO)pInfo)->szPortName ) ) <= ulLength )
            {
               WriteLogWithPrefix( "szPortName = \"%s\"\n", pInfo );
            }

            break;

         case 1:
            if ( ( FIELDOFFSET( PRPORTINFO1, pszPortName ) + sizeof( ((PPRPORTINFO1)pInfo)->pszPortName ) ) <= ulLength )
            {
               WriteLogWithPrefix( "pszPortName = " ); T_LogPSZ( ((PPRPORTINFO1)pInfo)->pszPortName );

               if ( ( FIELDOFFSET( PRPORTINFO1, pszPortDriverName ) + sizeof( ((PPRPORTINFO1)pInfo)->pszPortDriverName ) ) <= ulLength )
               {
                  WriteLogWithPrefix( "pszPortDriverName = " ); T_LogPSZ( ((PPRPORTINFO1)pInfo)->pszPortDriverName );

                  if ( ( FIELDOFFSET( PRPORTINFO1, pszPortDriverPathName ) + sizeof( ((PPRPORTINFO1)pInfo)->pszPortDriverPathName ) ) <= ulLength )
                  {
                     WriteLogWithPrefix( "pszPortDriverPathName = " ); T_LogPSZ( ((PPRPORTINFO1)pInfo)->pszPortDriverPathName );
                  }
               }
            }

            break;

         case 2:
            if ( ( FIELDOFFSET( PRPORTINFO2, pszPortName ) + sizeof( ((PPRPORTINFO2)pInfo)->pszPortName ) ) <= ulLength )
            {
               WriteLogWithPrefix( "pszPortName = " ); T_LogPSZ( ((PPRPORTINFO2)pInfo)->pszPortName );

               if ( ( FIELDOFFSET( PRPORTINFO2, pszPortDriver ) + sizeof( ((PPRPORTINFO2)pInfo)->pszPortDriver ) ) <= ulLength )
               {
                  WriteLogWithPrefix( "pszPortDriver = " ); T_LogPSZ( ((PPRPORTINFO2)pInfo)->pszPortDriver );

                  if ( ( FIELDOFFSET( PRPORTINFO2, pszProtocolConverter ) + sizeof( ((PPRPORTINFO2)pInfo)->pszProtocolConverter ) ) <= ulLength )
                  {
                     WriteLogWithPrefix( "pszProtocolConverter = " ); T_LogPSZ( ((PPRPORTINFO2)pInfo)->pszProtocolConverter );

                     if ( ( FIELDOFFSET( PRPORTINFO2, ulReserved ) + sizeof( ((PPRPORTINFO2)pInfo)->ulReserved ) ) <= ulLength )
                     {
                        WriteLogWithPrefix( "ulReserved = 0x%08lX\n", ((PPRPORTINFO2)pInfo)->ulReserved );

                        if ( ( FIELDOFFSET( PRPORTINFO2, ulMode ) + sizeof( ((PPRPORTINFO2)pInfo)->ulMode ) ) <= ulLength )
                        {
                           WriteLogWithPrefix( "ulMode = 0x%08lX\n", ((PPRPORTINFO2)pInfo)->ulMode );

                           if ( ( FIELDOFFSET( PRPORTINFO2, ulPriority ) + sizeof( ((PPRPORTINFO2)pInfo)->ulPriority ) ) <= ulLength )
                           {
                              WriteLogWithPrefix( "ulPriority = 0x%08lX\n", ((PPRPORTINFO2)pInfo)->ulPriority );
                           }
                        }
                     }
                  }
               }
            }

            break;
      }

      INDENTLOGOUT;
   }

}  /* LogPPRPORTINFO() */

