/******************************************************************************/

VOID LogPSTATUSDATA( PSTATUSDATA p )             /* PSTATUSDATA               */
{

   /*
    * Log status data structure contents if tracing API parameter contents
    * and valid pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, sizeof( USHORT ) ) ) && ( T_IsValidMem( p, p->Length ) ) )
   {
      INDENTLOGIN;
      WriteLogWithPrefix( "Length = 0x%04hX\n", p->Length );

      if ( ( FIELDOFFSET( STATUSDATA, SelectInd ) + sizeof( p->SelectInd ) ) <= p->Length )
      {
         WriteLogWithPrefix( "SelectInd = 0x%04hX\n", p->SelectInd );

         if ( ( FIELDOFFSET( STATUSDATA, BondInd ) + sizeof( p->BondInd ) ) <= p->Length )
         {
            WriteLogWithPrefix( "BondInd = 0x%04hX\n", p->BondInd );
         }
      }

      INDENTLOGOUT;
   }

}  /* LogPSTATUSDATA() */

