/******************************************************************************/
/*                                                                            */
/* LogRECTLBuffer()                                                           */
/*                                                                            */
/******************************************************************************/

VOID LogRECTLBuffer( PRECTL p                    /* RECTL buffer              */
                   , ULONG  ulNumber             /* Number RECTLs             */
                   )
{

   BOOL bMore = FALSE;                           /* Log more indicator        */
   int  i;                                       /* Loop variable             */

   /*
    * Log RECTL buffer contents if tracing API parameter contents and valid
    * pointer
    */
   if ( ( LOGLEVEL( L_CONTENTS ) ) && ( T_IsValidMem( p, ulNumber * sizeof( RECTL ) ) ) )
   {
      INDENTLOGIN;

      /*
       * Adjust number RECTLs if length greater than maximum buffer length
       */
      if ( ( ulMaxBufLen ) && ( ulMaxBufLen < ( ulNumber * sizeof( RECTL ) ) ) )
      {
         ulNumber = ulMaxBufLen / sizeof( RECTL );
         bMore = TRUE;
      }

      /*
       * Log RECTL buffer contents
       */
      for ( i = 0; i < ulNumber; i++, p++ )
      {
         WriteLogWithPrefix( "RECTL[ %d ]:\n", i );
         LogPRECTL( p );
      }

      /*
       * Log more contents string if so indicated
       */
      if ( bMore )
      {
         WriteLogWithPrefix( "%s\n", szMore );
      }

      INDENTLOGOUT;
   }

}  /* LogRECTLBuffer() */

